fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    if host::display::state_get(6) == 0 {
        host::display::state_set(6, 1);
        host::display::state_set(0, 30);
        host::display::state_set(1, 80);
    }
    let zx: i32 = w - 110;
    let zy: i32 = h - 110;
    let down: i32 = host::display::pointer_down();
    let prev: i32 = host::display::state_get(5);
    let px: i32 = host::display::pointer_x();
    let py: i32 = host::display::pointer_y();
    let mut x: i32 = host::display::state_get(0);
    let mut y: i32 = host::display::state_get(1);
    let mut drag: i32 = host::display::state_get(2);
    if down == 1 && prev == 0 {
        if px >= x && px < x + 48 && py >= y && py < y + 48 {
            drag = 1;
            host::display::state_set(3, px - x);
            host::display::state_set(4, py - y);
        }
    }
    if drag == 1 && down == 1 {
        x = px - host::display::state_get(3);
        y = py - host::display::state_get(4);
    }
    let over: i32 = if x + 24 >= zx && x + 24 < zx + 90 && y + 24 >= zy && y + 24 < zy + 90 { 1 } else { 0 };
    if drag == 1 && down == 0 {
        drag = 0;
        if over == 1 {
            x = zx + 21;
            y = zy + 21;
        }
    }
    host::display::state_set(0, x);
    host::display::state_set(1, y);
    host::display::state_set(2, drag);
    host::display::state_set(5, down);
    host::display::clear(0x101010);
    let zc: i32 = if over == 1 { 0x00ff88 } else { 0x505050 };
    host::display::fill_rect(zx, zy, 90, 90, zc);
    host::display::fill_rect(zx + 3, zy + 3, 84, 84, 0x101010);
    if over == 1 && drag == 0 {
        host::display::draw_string(zx, zy - 16, "DOCKED", 0x00ff88, 1);
    }
    let cc: i32 = if drag == 1 { 0xffaa00 } else { 0xcc7700 };
    host::display::fill_rect(x, y, 48, 48, cc);
    host::display::draw_string(8, 8, "DRAG THE CRATE TO THE DOCK", 0x808080, 1);
    host::display::present();
}
